 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # For each same-color diagonal run that progresses downward, extend the
    # ray from its topmost cell upward to the nearest grid edge.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == grid[0][0] and all(v == color for row in grid for v in row):
                continue
            for dc in (-1, 1):
                if r + 1 >= h or not (0 <= c + dc < w):
                    continue
                if grid[r + 1][c + dc] != color:
                    continue
                # Only start at the top of a maximal downward diagonal run.
                if r > 0 and 0 <= c - dc < w and grid[r - 1][c - dc] == color:
                    continue
                run = []
                rr, cc = r, c
                while rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += 1
                    cc += dc
                if len(run) < 2:
                    continue
                key = (color, r, c, dc)
                if key in seen:
                    continue
                seen.add(key)
                rr, cc = r - 1, c - dc
                while rr >= 0 and 0 <= cc < w:
                    out[rr][cc] = color
                    rr -= 1
                    cc -= dc
    return out

