 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]

    # Continue each foreground diagonal line backwards from its upper endpoint
    # until it reaches the edge of the canvas.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                nr, nc = r + 1, c + dc
                if nr >= h or not (0 <= nc < w) or grid[nr][nc] != color:
                    continue
                # Avoid starting partway along a same-color diagonal run.
                pr, pc = r - 1, c - dc
                if pr >= 0 and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                rr, cc = r - 1, c - dc
                while rr >= 0 and 0 <= cc < w:
                    out[rr][cc] = color
                    rr -= 1
                    cc -= dc
    return out
