 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    # From a bottom horizontal pair of equal colors, continue the diagonals
    # emanating from the pair upward to the grid edge.
    starts = []
    for r in range(h - 1):
        for c in range(w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a != background and a == b:
                # Pair should have the same color pair directly below, as in
                # the seed motif; trace both outward-facing rays.
                if grid[r + 1][c] == a and grid[r + 1][c + 1] == a:
                    starts.extend([(r, c, -1), (r, c + 1, 1)])
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] == background:
                continue
            # Also detect two-cell diagonal streaks and extend them upward.
            for dc in (-1, 1):
                nr, nc = r + 1, c + dc
                if nr < h and 0 <= nc < w and grid[nr][nc] == grid[r][c]:
                    starts.append((r, c, dc))

    for r, c, dc in starts:
        rr, cc = r - 1, c - dc
        color = grid[r][c]
        while rr >= 0 and 0 <= cc < w:
            if out[rr][cc] == background:
                out[rr][cc] = color
            rr -= 1
            cc -= dc
    return out


def _check_demo2():
    x = [[2] * 26 for _ in range(7)]
    x[4][16] = 5; x[4][19] = 9
    x[5][17] = 5; x[5][18] = 9
    x[6][17] = 8; x[6][18] = 5
    y = [row[:] for row in x]
    for r in range(4):
        y[r][12 + r] = 5
        y[r][23 - r] = 9
    assert transform(x) == y

if __name__ == '__main__':
    _check_demo2()
    print('demo2 reproduced')
",
 "cross_profile": false
}

