 "content": "from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # A diagonal pattern triggers rays extending outward from the connected
    # colored diagonal fragments. Extend from each endpoint until boundary.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr
                    cc += dc
                for rr, cc, sr, sc in (
                    (run[0][0] - dr, run[0][1] - dc, -dr, -dc),
                    (run[-1][0] + dr, run[-1][1] + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out


def _demo8_check():
    g = [[8]*11 for _ in range(13)]
    g[6][3]=5;g[6][6]=5;g[7][4]=5;g[7][5]=5
    g[8][4]=1;g[8][5]=9;g[9][3]=1;g[9][6]=9
    expected=[row[:] for row in g]
    for r in range(2,6):
        expected[r][10-r]=5
        expected[r][r-1]=5
    for r in range(10,13):
        expected[r][r-8]=1
        expected[r][r-1]=9
    assert transform(g)==expected

if __name__ == '__main__':
    _demo8_check()
    print('demo 8 reproduced')

